import{_ as s,o as n,c as p,a2 as i}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"支付策略引擎：如何限制 Agent 的消费","description":"","frontmatter":{},"headers":[],"relativePath":"zh/learn/02-agent-payments/spending-policy.md","filePath":"zh/learn/02-agent-payments/spending-policy.md","lastUpdated":1792545482000}'),e={name:"zh/learn/02-agent-payments/spending-policy.md"};function l(t,a,h,d,c,o){return n(),p("div",null,[...a[0]||(a[0]=[i(`<h1 id="支付策略引擎-如何限制-agent-的消费" tabindex="-1">支付策略引擎：如何限制 Agent 的消费 <a class="header-anchor" href="#支付策略引擎-如何限制-agent-的消费" aria-label="Permalink to &quot;支付策略引擎：如何限制 Agent 的消费&quot;">​</a></h1><h2 id="一、为什么需要支付策略引擎" tabindex="-1">一、为什么需要支付策略引擎？ <a class="header-anchor" href="#一、为什么需要支付策略引擎" aria-label="Permalink to &quot;一、为什么需要支付策略引擎？&quot;">​</a></h2><p>假设你给一个研究 Agent 提供了 10 USDC 的预算，让它自动购买数据服务。</p><p>它可能正常调用 API，也可能因为模型误判、任务循环或恶意输入，反复购买不必要的数据。</p><p>如果系统只提供钱包和支付接口，那么只要 Agent 能够发起有效支付，就可能持续消费。</p><p>支付策略引擎（Spending Policy Engine）就是为了在支付执行之前，对请求进行独立的规则检查。</p><p>可以把它理解为银行账户的消费规则与 API 网关的访问控制相结合的一层系统。</p><h2 id="二、支付策略引擎的基本流程" tabindex="-1">二、支付策略引擎的基本流程 <a class="header-anchor" href="#二、支付策略引擎的基本流程" aria-label="Permalink to &quot;二、支付策略引擎的基本流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 提出支付请求</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>验证 Agent 身份</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>检查服务商</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>检查单笔金额</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>检查预算</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>检查调用频率</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>检查风险与审批要求</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>允许 / 拒绝 / 等待审批</span></span></code></pre></div><p>这里的“允许”意味着请求通过了策略检查，并不等于资金已经完成结算。</p><p>后续仍需要执行授权、支付、交付和状态更新等流程。</p><h2 id="三、第一类规则-单笔支付限额" tabindex="-1">三、第一类规则：单笔支付限额 <a class="header-anchor" href="#三、第一类规则-单笔支付限额" aria-label="Permalink to &quot;三、第一类规则：单笔支付限额&quot;">​</a></h2><p>单笔限额用于限制一次请求最多可以花多少钱。</p><p>例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_transaction_amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.10</span></span></code></pre></div><p>假设金额单位为 USDC。</p><p>那么：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 A：0.05 USDC → 允许继续检查</span></span>
<span class="line"><span>请求 B：0.10 USDC → 允许继续检查</span></span>
<span class="line"><span>请求 C：0.20 USDC → 拒绝</span></span></code></pre></div><p>注意，前两个请求只是通过单笔限额检查，还需要满足其他规则。</p><p>单笔限额也不能代替预算限制。即使每次只花 0.01 USDC，连续调用很多次仍然可能产生较高成本。</p><h2 id="四、第二类规则-时间窗口预算" tabindex="-1">四、第二类规则：时间窗口预算 <a class="header-anchor" href="#四、第二类规则-时间窗口预算" aria-label="Permalink to &quot;四、第二类规则：时间窗口预算&quot;">​</a></h2><p>时间窗口预算用于限制一定时间范围内的累计消费。</p><p>例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">budget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  daily</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.00</span></span></code></pre></div><p>这里的 <code>daily</code> 需要在实际系统中明确是自然日预算还是滚动 24 小时预算。</p><p>假设采用滚动 24 小时预算，Agent 当前已经使用 1.80 USDC，剩余 0.20 USDC。</p><p>此时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 A：0.05 USDC → 预算允许</span></span>
<span class="line"><span>请求 B：0.25 USDC → 预算不足</span></span></code></pre></div><p>真实实现需要明确预算统计范围、时区、过期记录和并发处理规则。</p><p>对于 AgentPay MVP，研发计划采用滚动 24 小时预算，并计划使用 SQLite 事务实现原子预留。</p><h2 id="五、第三类规则-商户白名单" tabindex="-1">五、第三类规则：商户白名单 <a class="header-anchor" href="#五、第三类规则-商户白名单" aria-label="Permalink to &quot;五、第三类规则：商户白名单&quot;">​</a></h2><p>商户白名单用于限定 Agent 可以向哪些服务商付款。</p><p>例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allowed_merchants</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">search-api</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">market-data</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">translation-api</span></span></code></pre></div><p>如果 Agent 请求向 <code>unknown-service</code> 付款，即使金额只有 0.001 USDC，也应该因为服务商不在允许范围内而被拒绝。</p><p>白名单中的名称还必须与可信的服务身份建立可靠映射。</p><p>不能只相信服务端在请求中随意提供的一个名称，就把它当成可信商户身份。</p><p>在实际系统中，需要根据具体协议设计对收款方、服务标识和支付要求的验证方式。</p><h2 id="六、第四类规则-调用频率限制" tabindex="-1">六、第四类规则：调用频率限制 <a class="header-anchor" href="#六、第四类规则-调用频率限制" aria-label="Permalink to &quot;六、第四类规则：调用频率限制&quot;">​</a></h2><p>频率限制用于控制单位时间内的请求数量。</p><p>例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  requests_per_minute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span></code></pre></div><p>假设 Agent 每分钟最多允许发起 10 次付费请求。</p><p>这有助于限制：</p><ul><li>无限调用循环。</li><li>重复请求。</li><li>异常高频消费。</li><li>某些滥用行为。</li></ul><p>但频率限制不等于预算限制。</p><p>如果每次请求费用不同，单纯限制请求数量并不能准确限制总消费。</p><p>因此，频率限制应与单笔限额、累计预算共同使用。</p><h2 id="七、第五类规则-生命周期总额" tabindex="-1">七、第五类规则：生命周期总额 <a class="header-anchor" href="#七、第五类规则-生命周期总额" aria-label="Permalink to &quot;七、第五类规则：生命周期总额&quot;">​</a></h2><p>生命周期限额用于限制某个 Agent 在整个授权周期内可以使用的累计金额。</p><p>例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">budget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  lifetime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20.00</span></span></code></pre></div><p>假设某个 Agent 从创建至今累计消费了 19.90 USDC。</p><p>即使它今天的预算仍然充足，新的 0.20 USDC 请求也应该因为超过生命周期限额而被拒绝。</p><p>实际系统需要定义累计消费是否包括失败请求、退款和预留中的金额，并明确如何处理额度恢复。</p><h2 id="八、第六类规则-人工审批" tabindex="-1">八、第六类规则：人工审批 <a class="header-anchor" href="#八、第六类规则-人工审批" aria-label="Permalink to &quot;八、第六类规则：人工审批&quot;">​</a></h2><p>并不是所有支付请求都适合自动通过。</p><p>例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">approval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  required_above</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.00</span></span></code></pre></div><p>这里表示超过 1 USDC 的请求需要进入审批流程，具体字段语义需要由系统定义。</p><p>审批可以采用这样的流程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 请求支付</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>策略检查</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>金额超过审批阈值</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>进入待审批状态</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>人工确认</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>重新验证授权与支付参数</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>继续执行</span></span></code></pre></div><p>需要注意，审批结果必须绑定具体请求和参数。</p><p>如果审批后金额、收款方或其他关键字段发生变化，就不能直接沿用原来的审批结果。</p><h2 id="九、预算预留-为什么必须先锁定额度" tabindex="-1">九、预算预留：为什么必须先锁定额度？ <a class="header-anchor" href="#九、预算预留-为什么必须先锁定额度" aria-label="Permalink to &quot;九、预算预留：为什么必须先锁定额度？&quot;">​</a></h2><p>这是支付策略引擎中一个重要的工程问题。</p><p>假设剩余预算为 1 USDC，两个请求同时申请 0.70 USDC。</p><p>如果系统只检查余额而不预留额度，就可能同时批准两个请求。</p><p>因此，预算控制应当采用类似以下流程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查可用预算</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>原子预留额度</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>执行支付流程</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>根据最终结果更新预算</span></span></code></pre></div><p>可以把预算分为三个概念：</p><ul><li><code>available</code>：可用预算。</li><li><code>reserved</code>：已经为待处理请求预留的预算。</li><li><code>spent</code>：已确认消耗的预算。</li></ul><p>在一个简单模型中：</p><p>[ available = limit - spent - reserved ]</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总预算：10.00</span></span>
<span class="line"><span>已消耗：3.00</span></span>
<span class="line"><span>已预留：2.00</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可用预算：5.00</span></span></code></pre></div><p>如果新的请求需要 6.00，就不能再批准。</p><p>实际系统还需要定义预留过期、失败释放、未知支付状态以及退款等场景的处理规则。</p><p><strong>对于结果未知的支付请求，不能仅因为超时就直接释放预算。</strong> 否则系统可能在第一次支付已经成功的情况下，又批准新的消费，突破原有预算约束。</p><h2 id="十、策略引擎如何处理异常" tabindex="-1">十、策略引擎如何处理异常？ <a class="header-anchor" href="#十、策略引擎如何处理异常" aria-label="Permalink to &quot;十、策略引擎如何处理异常？&quot;">​</a></h2><p>一个实用的策略引擎至少需要区分以下结果：</p><table tabindex="0"><thead><tr><th>结果</th><th>含义</th><th>后续动作</th></tr></thead><tbody><tr><td>ALLOW</td><td>请求满足策略条件</td><td>进入后续授权与支付流程</td></tr><tr><td>DENY</td><td>请求违反策略</td><td>拒绝执行并记录原因</td></tr><tr><td>REQUIRE_APPROVAL</td><td>需要人工审批</td><td>进入审批流程</td></tr><tr><td>TEMPORARY_FAILURE</td><td>暂时无法完成策略判断</td><td>按明确规则等待、重试或拒绝</td></tr><tr><td>CIRCUIT_OPEN</td><td>熔断器已打开</td><td>暂停相关请求</td></tr></tbody></table><p>这些状态是便于理解的设计示例，不是某个协议规定的固定枚举。</p><p>策略判断本身发生异常时，不应默认放行。</p><p>对资金相关操作，通常应采用失败关闭（Fail Closed）的思路：无法确认请求满足必要的安全条件时，不继续执行支付。</p><h2 id="十一、熔断器-防止-agent-失控消费" tabindex="-1">十一、熔断器：防止 Agent 失控消费 <a class="header-anchor" href="#十一、熔断器-防止-agent-失控消费" aria-label="Permalink to &quot;十一、熔断器：防止 Agent 失控消费&quot;">​</a></h2><p>假设一个 Agent 因为循环错误，连续向同一个服务发起请求。</p><p>系统可以综合以下信号：</p><ul><li>同一 Agent 的请求频率。</li><li>同一资源的重复调用次数。</li><li>连续失败次数。</li><li>一段时间内的消费金额。</li><li>是否出现异常重试行为。</li></ul><p>达到规则阈值后，熔断器可以阻断相关支付请求。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 连续触发异常</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>达到熔断阈值</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>CIRCUIT OPEN</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>拒绝新的付费请求</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>等待检查或恢复条件</span></span></code></pre></div><p>熔断器不能只靠模型自行决定何时停止。</p><p>它应该由应用程序独立执行，并具备明确的触发条件和恢复规则。</p><h2 id="十二、agentpay-mvp-应该先实现哪些策略" tabindex="-1">十二、AgentPay MVP 应该先实现哪些策略？ <a class="header-anchor" href="#十二、agentpay-mvp-应该先实现哪些策略" aria-label="Permalink to &quot;十二、AgentPay MVP 应该先实现哪些策略？&quot;">​</a></h2><p>结合项目年底研发计划，建议优先实现以下最小集合：</p><ol><li>单笔支付上限。</li><li>商户白名单。</li><li>生命周期限额。</li><li>滚动 24 小时预算。</li><li>基于原子预留的并发预算控制。</li><li>调用频率限制。</li><li>基础熔断机制。</li></ol><p>更复杂的风险评分、动态定价、复杂审批工作流可以放到后续阶段。</p><p>原因很简单：先把确定性规则做对，比一开始就引入复杂的 AI 风险评分更容易验证，也更容易测试。</p><h2 id="十三、小结" tabindex="-1">十三、小结 <a class="header-anchor" href="#十三、小结" aria-label="Permalink to &quot;十三、小结&quot;">​</a></h2><p>支付策略引擎的任务不是判断 Agent 的所有决策是否聪明，而是确定一个支付请求是否满足预先设定的规则。</p><p>它至少需要控制：</p><ul><li>单笔金额。</li><li>累计预算。</li><li>服务商范围。</li><li>调用频率。</li><li>生命周期额度。</li><li>审批条件。</li><li>异常与熔断。</li></ul><p>其中，预算预留、并发安全和异常状态处理尤其重要。</p><p><strong>策略引擎的价值，在于让 Agent 的消费行为受到独立、明确、可测试的程序规则约束。</strong></p><h2 id="下一篇" tabindex="-1">下一篇 <a class="header-anchor" href="#下一篇" aria-label="Permalink to &quot;下一篇&quot;">​</a></h2><p><a href="./payment-state-and-idempotency">支付状态机、幂等与故障恢复</a></p>`,107)])])}const k=s(e,[["render",l]]);export{g as __pageData,k as default};
